                     >
                 > with get, set

            abstract status: UnboundRuns.Status with get, set
            abstract display: option<``.``.AgentToolTypesDSteYkkSJs.AgentToolDisplayMetadata> with get, set
            abstract order: float with get, set
            abstract inputPreview: option<obj> with get, set
            abstract parentToolCallId: option<string> with get, set
            abstract agentType: string with get, set
            abstract runId: string with get, set
            abstract icon: option<string> with get, set
            abstract name: option<string> with get, set
            abstract Item: key: string -> option<AgentContext>

    module rec AgentToolRunState =
        module rec Input =
            type Vocabulary =
                abstract Item: key: string -> option<AgentContext>

        type Approval =
            abstract reason: option<string> with get, set
            abstract approved: Approval.Approved with get, set
            abstract id: string with get, set
            abstract approved: bool with get, set
            abstract reason: option<unit> with get, set
            abstract approved: option<unit> with get, set

